<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Services\AuditService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class ReminderController extends Controller{public function reminders(Request $r):JsonResponse{return $this->success(['items'=>DB::table('reminders')->where('organization_id',$r->attributes->get('organization_id'))->orderBy('due_at')->get()->map(fn($x)=>$this->reminder($x))]);}public function store(Request $r):JsonResponse{$d=$r->validate(['title'=>['required','string','max:255'],'dueAt'=>['required','date'],'entityType'=>['nullable','string','max:80'],'entityId'=>['nullable','uuid'],'recipientUserId'=>['nullable','integer']]);$org=$r->attributes->get('organization_id');$id=(string)Str::uuid();DB::table('reminders')->insert(['id'=>$id,'organization_id'=>$org,'title'=>$d['title'],'due_at'=>$d['dueAt'],'entity_type'=>$d['entityType']??null,'entity_id'=>$d['entityId']??null,'recipient_user_id'=>$d['recipientUserId']??$r->user()->id,'status'=>'scheduled','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$x=DB::table('reminders')->find($id);AuditService::record($org,$r->user()->id,'reminder.created','reminder',$id,null,$this->reminder($x));return $this->success($this->reminder($x),[],201);}public function update(Request $r,string $id):JsonResponse{$d=$r->validate(['status'=>['required','in:scheduled,completed,cancelled']]);$org=$r->attributes->get('organization_id');$x=DB::table('reminders')->where('organization_id',$org)->where('id',$id)->first();if(!$x)abort(404);DB::table('reminders')->where('id',$id)->update(['status'=>$d['status'],'updated_at'=>now()]);AuditService::record($org,$r->user()->id,'reminder.updated','reminder',$id,['status'=>$x->status],['status'=>$d['status']]);return $this->success($this->reminder(DB::table('reminders')->find($id)));}public function notifications(Request $r):JsonResponse{return $this->success(['items'=>DB::table('notifications')->where('organization_id',$r->attributes->get('organization_id'))->where('user_id',$r->user()->id)->latest('created_at')->get()->map(fn($x)=>$this->notification($x))]);}public function read(Request $r,string $id):JsonResponse{$x=DB::table('notifications')->where('organization_id',$r->attributes->get('organization_id'))->where('user_id',$r->user()->id)->where('id',$id)->first();if(!$x)abort(404);DB::table('notifications')->where('id',$id)->update(['read_at'=>now()]);return $this->success($this->notification(DB::table('notifications')->find($id)));}public function readAll(Request $r):JsonResponse{DB::table('notifications')->where('organization_id',$r->attributes->get('organization_id'))->where('user_id',$r->user()->id)->whereNull('read_at')->update(['read_at'=>now()]);return $this->success(['ok'=>true]);}private function reminder(object $x):array{return ['id'=>$x->id,'title'=>$x->title,'dueAt'=>$x->due_at,'status'=>$x->status,'entityType'=>$x->entity_type,'entityId'=>$x->entity_id];}private function notification(object $x):array{return ['id'=>$x->id,'type'=>$x->notification_type,'title'=>$x->title,'body'=>$x->body,'deepLink'=>$x->deep_link,'readAt'=>$x->read_at,'createdAt'=>$x->created_at];}}
